pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 must have the same length as vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");

    // Overwrite any previous contents; output must be exactly length n.
    avgs.clear();
    avgs.reserve_exact(n);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        debug_assert!(c1 || c2, "At least one condition must be true at each index");

        let out = match (c1, c2) {
            (true, true) => (vals_1[i] + vals_2[i]) / 2, // safe due to < 1000 constraint
            (true, false) => vals_1[i],
            (false, true) => vals_2[i],
            (false, false) => unreachable!("Contract violated: both conditions false"),
        };

        avgs.push(out);
    }

    debug_assert_eq!(avgs.len(), n);
}